"""`.Light Rotation Catcher`: generated by export_nodes.py from library.blend; kept by hand from then on."""

NAME = '.Light Rotation Catcher'
KIND = 'GeometryNodeTree'


def build(lib):
    t = lib.new_group(NAME, KIND, props={
            'node_tool_idname': 'geometry.light_rotation_catcher',
        })

    t.socket('OUTPUT', 'Geometry', 'NodeSocketGeometry')
    t.socket('INPUT', 'Geometry', 'NodeSocketGeometry')
    t.socket('INPUT', 'SDF Light', 'NodeSocketObject')

    t.node('NodeGroupInput', 'Group Input', props={
        'location': (-1360.6871, -22.941847),
    })
    t.node('NodeGroupOutput', 'Group Output', props={
        'location': (610.8623, 0.0),
    })
    t.node('GeometryNodeObjectInfo', 'Object Info', props={
        'location': (-1055.5721, -85.04085),
    })
    t.node('ShaderNodeCombineXYZ', 'Combine XYZ', inputs={'Z': 1.0}, props={
        'location': (-1055.8289, -291.87357),
    })
    t.node('FunctionNodeRotateVector', 'Rotate Vector', props={
        'location': (-770.2978, -76.436874),
    })
    t.node('GeometryNodeStoreNamedAttribute', 'Store Named Attribute', inputs={'Name': 'bl846388'}, props={
        'location': (-490.1164, 48.258636),
        'width': 172.21793,
        'data_type': 'FLOAT_VECTOR',
    })
    t.node('GeometryNodeStoreNamedAttribute', 'Store Named Attribute.001', inputs={'Name': 'rl846388'}, props={
        'location': (-124.22241, 48.258636),
        'width': 171.02454,
        'data_type': 'FLOAT_VECTOR',
    })
    t.node('GeometryNodeObjectInfo', 'Object Info.001', props={
        'location': (-1055.5721, -429.92908),
    })
    t.node('FunctionNodeRotateVector', 'Rotate Vector.001', props={
        'location': (-765.0116, -277.3904),
    })
    t.node('GeometryNodeStoreNamedAttribute', 'Store Named Attribute.002', inputs={'Name': 'sdf92748'}, props={
        'location': (238.42201, 51.84649),
        'width': 169.83131,
    })
    t.node('GeometryNodeObjectInfo', 'Object Info.002', props={
        'location': (-1055.5721, -636.1287),
    })
    t.node('FunctionNodeRotateVector', 'Rotate Vector.002', props={
        'location': (-765.0116, -474.0443),
    })
    t.node('ShaderNodeSeparateXYZ', 'Separate XYZ', props={
        'location': (-525.36816, -462.39896),
    })
    t.node('ShaderNodeMath', 'Math', inputs={'Value_001': -1.0}, props={
        'location': (-314.92603, -555.5966),
        'operation': 'MULTIPLY',
    })
    t.node('ShaderNodeMath', 'Math.001', props={
        'location': (-124.042076, -397.0621),
        'operation': 'ARCTAN2',
    })

    t.link('Store Named Attribute.002', 'Geometry', 'Group Output', 'Geometry')
    t.link('Object Info', 'Rotation', 'Rotate Vector', 'Rotation')
    t.link('Combine XYZ', 'Vector', 'Rotate Vector', 'Vector')
    t.link('Group Input', 'Geometry', 'Store Named Attribute', 'Geometry')
    t.link('Store Named Attribute', 'Geometry', 'Store Named Attribute.001', 'Geometry')
    t.link('Combine XYZ', 'Vector', 'Rotate Vector.001', 'Vector')
    t.link('Object Info.001', 'Rotation', 'Rotate Vector.001', 'Rotation')
    t.link('Rotate Vector', 'Vector', 'Store Named Attribute', 'Value')
    t.link('Rotate Vector.001', 'Vector', 'Store Named Attribute.001', 'Value')
    t.link('Store Named Attribute.001', 'Geometry', 'Store Named Attribute.002', 'Geometry')
    t.link('Group Input', 'SDF Light', 'Object Info.002', 'Object')
    t.link('Combine XYZ', 'Vector', 'Rotate Vector.002', 'Vector')
    t.link('Object Info.002', 'Rotation', 'Rotate Vector.002', 'Rotation')
    t.link('Rotate Vector.002', 'Vector', 'Separate XYZ', 'Vector')
    t.link('Separate XYZ', 'Y', 'Math', 'Value')
    t.link('Separate XYZ', 'X', 'Math.001', 'Value')
    t.link('Math', 'Value', 'Math.001', 'Value_001')
    t.link('Math.001', 'Value', 'Store Named Attribute.002', 'Value')
    return t
